set_db fail_on_error_mesg true
read_db {/home/downeyflyfan/Research_Projects/Hardware/Attention_Accelerator/.cache/physical/synthesis/tri_oracle_predicted_feedforward_hierarchical144/elaborated.db}
foreach phase {restored root_none all_scopes_none} {
    if {$phase eq "root_none"} {set_db / .control_logic_optimization none}
    if {$phase eq "all_scopes_none"} {
        set_db [get_db designs] .control_logic_optimization none
        set_db [get_db modules] .control_logic_optimization none
    }
    puts "QUERY148_PHASE $phase ROOT [get_db / .control_logic_optimization]"
    foreach design [get_db designs] {puts "QUERY148_DESIGN [get_db $design .name] [get_db $design .control_logic_optimization]"}
    foreach module [get_db modules] {puts "QUERY148_MODULE [get_db $module .name] [get_db $module .control_logic_optimization]"}
}
puts QUERY148_COMPLETED
exit
